var WA='919737133331';
var REDUCE=matchMedia('(prefers-reduced-motion:reduce)').matches;

/* ---------- analytics events (do nothing until the GA4 tag is added) ---------- */
function track(name,params){ try{ if(typeof gtag==='function') gtag('event',name,params||{}); }catch(e){} }
document.addEventListener('click',function(e){
  var a=e.target.closest('a,button'); if(!a) return;
  var href=a.getAttribute('href')||'', ev=a.getAttribute('data-ev');
  if(ev) track(ev);
  if(href.indexOf('wa.me')>-1) track('whatsapp_click');
  else if(href.indexOf('mailto:')===0) track('email_click');
  else if(href.indexOf('tel:')===0) track('phone_click');
});

/* ---------- scroll reveal ---------- */
(function(){
  var els=[].slice.call(document.querySelectorAll('[data-rv]'));
  function show(el){ el.classList.add('in'); }
  if(!('IntersectionObserver' in window) || REDUCE){ els.forEach(show); return; }
  var fired=false;
  var io=new IntersectionObserver(function(es){
    fired=true; es.forEach(function(e){ if(e.isIntersecting){ show(e.target); io.unobserve(e.target); } });
  },{threshold:.1, rootMargin:'0px 0px -6% 0px'});
  els.forEach(function(el){ io.observe(el); });
  /* safety net: never leave content invisible */
  setTimeout(function(){ if(!fired) els.forEach(show); },2500);
})();

