function sendQuote(){
  var g=function(id){ var el=document.getElementById(id); return el?el.value.trim():''; };
  var cut=function(s,n){ return s?s.slice(0,n):null; };
  if(g('cWeb')) return;                      /* spam trap was filled in: a bot, ignore it */
  var name=g('cName'), phone=g('cPhone');
  if(!name && !phone){ alert('Please enter at least your name and phone number so we can reach you.'); return; }
  saveEnquiry({ name:cut(name,80), phone:cut(phone,20), email:cut(g('cEmail'),120), business:cut(g('cBiz'),120),
    service:cut(g('cService'),60), budget:cut(g('cBudget'),40), message:cut(g('cMsg'),1000), page:cut(location.pathname,200) });
  var text="Hi! I'd like to discuss a project with Repute India AI.\n\n"
    +"Name: "+(name||'—')+"\nPhone: "+(phone||'—')+"\nEmail: "+(g('cEmail')||'—')
    +"\nBusiness: "+(g('cBiz')||'—')+"\nService: "+(g('cService')||'—')+"\nBudget: "+(g('cBudget')||'—')
    +(g('cMsg')?("\nMessage: "+g('cMsg')):'')+"\n\nPlease get in touch. Thank you!";
  track('generate_lead',{ service:g('cService'), budget:g('cBudget') });
  window.open('https://wa.me/'+WA+'?text='+encodeURIComponent(text),'_blank');
}

/* ---------- nav, mobile menu, mobile action bar ---------- */
(function(){
  var nav=document.getElementById('nav'), dock=document.getElementById('dock'),
      btn=document.getElementById('menuBtn'), sheet=document.getElementById('sheet'),
      contact=document.getElementById('contact'), ticking=false;
  function onScroll(){
    if(ticking) return; ticking=true;
    requestAnimationFrame(function(){
      nav.classList.toggle('scrolled', scrollY>24);
      var nearContact=contact.getBoundingClientRect().top < innerHeight*.6;
      dock.classList.toggle('up', scrollY>520 && !nearContact);
      ticking=false;
    });
  }
  addEventListener('scroll',onScroll,{passive:true}); onScroll();
  function setMenu(open){
    document.body.classList.toggle('menu-open',open);
    btn.setAttribute('aria-expanded',open?'true':'false');
    btn.setAttribute('aria-label',open?'Close menu':'Open menu');
    sheet.setAttribute('aria-hidden',open?'false':'true');
  }
  btn.addEventListener('click',function(){ setMenu(!document.body.classList.contains('menu-open')); });
  sheet.addEventListener('click',function(e){ if(e.target.closest('a')) setMenu(false); });
  addEventListener('keydown',function(e){ if(e.key==='Escape') setMenu(false); });
  document.getElementById('yr').textContent=new Date().getFullYear();
})();

/* ---------- count-up ---------- */
(function(){
  if(REDUCE || !('IntersectionObserver' in window)) return;
  document.querySelectorAll('[data-count]').forEach(function(el){
    var t=parseFloat(el.getAttribute('data-count'));
    var o=new IntersectionObserver(function(es){
      if(!es[0].isIntersecting) return; o.disconnect(); var s=null; el.textContent='0';
      requestAnimationFrame(function step(ts){
        if(s===null) s=ts; var p=Math.min((ts-s)/1100,1);
        el.textContent=Math.round(t*(1-Math.pow(1-p,3)));
        if(p<1) requestAnimationFrame(step); else el.textContent=t;
      });
    },{threshold:.6});
    o.observe(el);
  });
})();

/* ---------- AI Search pricing: market switcher ---------- */
(function(){
  var P={
    in:{pre:'₹',   m:[4999,12999,29999], s:[7000,12000,20000], loc:'en-IN',
        note:'<b>Already a Repute client?</b>Setup fee waived and 15% off the monthly fee when you add this to your website or CRM plan.'},
    ae:{pre:'AED ',m:[799,1999,3999]}, uk:{pre:'£',m:[179,449,899]},
    au:{pre:'A$',  m:[349,849,1699]},  us:{pre:'$',m:[219,549,1099]},
    ea:{pre:'US$', m:[59,119,209],
        note:'<b>East Africa · priced in US dollars</b>Setup fee is one month\'s fee. Same 6-month minimum. Payment by bank transfer or card, M-Pesa on request.'}
  };
  var OVERSEAS='<b>Setup fee</b>For overseas clients the one-time setup fee is one month\'s fee. Same 6-month minimum.';
  var bar=document.getElementById('cur'), grid=document.getElementById('planGrid'), note=document.getElementById('bundleNote');
  if(!bar||!grid) return;
  function fmt(c,n){ return c.pre + n.toLocaleString(c.loc||'en-US'); }
  function paint(k){
    var c=P[k];
    grid.querySelectorAll('[data-m]').forEach(function(el){ el.textContent=fmt(c,c.m[+el.getAttribute('data-m')]); });
    grid.querySelectorAll('[data-s]').forEach(function(el){ var i=+el.getAttribute('data-s'); el.textContent=fmt(c,(c.s||c.m)[i]); });
    if(note) note.innerHTML=c.note||OVERSEAS;
  }
  bar.addEventListener('click',function(e){
    var b=e.target.closest('[data-cur]'); if(!b||b.classList.contains('on')) return;
    bar.querySelectorAll('button').forEach(function(x){ x.classList.toggle('on',x===b); });
    var k=b.getAttribute('data-cur');
    if(REDUCE){ paint(k); return; }
    grid.classList.add('swap');
    setTimeout(function(){ paint(k); grid.classList.remove('swap'); },240);
  });
})();

